def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the repeated, multicolored stripe that gives the stack order.
    candidates = []
    r = 0
    while r < h:
        end = r + 1
        while end < h and grid[end] == grid[r]:
            end += 1
        height = end - r
        if height >= 2:
            c = 0
            while c < w:
                if grid[r][c] == 0:
                    c += 1
                    continue
                left = c
                while c < w and grid[r][c] != 0:
                    c += 1
                colors = grid[r][left:c]
                if len(set(colors)) > 1:
                    candidates.append((height * len(colors), r, end, left, c))
        r = end

    if not candidates:
        return [row[:] for row in grid]

    _, pal_top, pal_bottom, pal_left, pal_right = max(candidates)
    palette = grid[pal_top][pal_left:pal_right]
    excluded = {
        (rr, cc)
        for rr in range(pal_top, pal_bottom)
        for cc in range(pal_left, pal_right)
    }

    # Find the largest single-color connected component outside the palette.
    seen = set()
    components = []
    for rr in range(h):
        for cc in range(w):
            color = grid[rr][cc]
            if color == 0 or (rr, cc) in excluded or (rr, cc) in seen:
                continue
            stack = [(rr, cc)]
            seen.add((rr, cc))
            comp = []
            while stack:
                cr, ccol = stack.pop()
                comp.append((cr, ccol))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = cr + dr, ccol + dc
                        if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in excluded and
                            (nr, nc) not in seen and
                            grid[nr][nc] == color):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            components.append((len(comp), color, comp))

    if not components:
        return [row[:] for row in grid]

    _, source_color, comp = max(components, key=lambda x: x[0])
    top = min(rr for rr, _ in comp)
    left = min(cc for _, cc in comp)
    bottom = max(rr for rr, _ in comp)
    right = max(cc for _, cc in comp)
    shape_h, shape_w = bottom - top + 1, right - left + 1
    mask = {(rr - top, cc - left) for rr, cc in comp}

    source_index = palette.index(source_color) if source_color in palette else 0
    stack_top = top - source_index * shape_h

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        copy_top = stack_top + i * shape_h
        for dr, dc in mask:
            rr, cc = copy_top + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
